@Experimental
record NativeValueOutcome(Kind kind, Value value) {
	enum Kind {
		BOUND,
		UNBOUND,
		ERROR
	}

	static final NativeValueOutcome UNBOUND = new NativeValueOutcome(Kind.UNBOUND, null);
	static final NativeValueOutcome ERROR = new NativeValueOutcome(Kind.ERROR, null);

	static NativeValueOutcome bound(Value value) {
		return value == null ? UNBOUND : new NativeValueOutcome(Kind.BOUND, value);
	}

	boolean isBound() {
		return kind == Kind.BOUND;
	}
}

